    GridWidget.prototype._initialize = function () {
        var self = this;
        self.$el.empty();
        // set widget class
        self.$el.addClass(WIDGET_CLASS);
        
        self._tableSetup = false;
    };

    GridWidget.prototype.setupTable = function() {
        var self = this;
        let nodeActiveId = WebGMEGlobal.State.getActiveObject();
        let nodeActive =  self._client.getNode(nodeActiveId);
        let onEmptyItems = [];
        let nodeName = nodeActive ? nodeActive.getAttribute('name') : null;
        nodeName = nodeName === 'ROOT' ? '' : nodeName;
        let template = SelectorGridHtml.replace('<%=modelName%>',nodeName);
        self.$el.empty();
        self.$el.append(template);
        self.$table = self.$el.find('#rootVizTable');
        self.$el.off();
        if(!this.createControl) {            
            self._tableSetup = true;
            if (nodeActive){
                let metaNodes = self._client.getAllMetaNodes();
                let validMetaChilds = nodeActive.getValidChildrenMetaIds(metaNodes);
                
                validMetaChilds.forEach(path=>{
                    let childMetaNode = self._client.getNode(path);
                    if(childMetaNode.getAttribute('name') !== 'Note' && !childMetaNode.isAbstract()){
                        onEmptyItems.push({
                            name: 'New '+childMetaNode.getAttribute('name'),
                            icon: '',
                            doNotHide: false,
                            callback: self.newChild.bind(self, path)
                        });
                    }
                });
            }
        }
        // default handlers for the rest of the viz space
        self.$el.on('contextmenu', (event) => {
            var posX = event.clientX;
            var posY = event.clientY;
            self.cm = new ContextMenu({
                items: onEmptyItems,
                callback: function(key) {
                    onEmptyItems[key].callback();
                    self.cm.destroy();
                }
            });
    
            self.cm.show({x: posX, y: posY});

            event.stopPropagation();
            event.preventDefault();
        });
        this.createControl = false;
    };
    GridWidget.prototype.createNodeEntry = function (desc) {
        var self = this;
        if (!self._tableSetup)
            self.setupTable();

        self.updateNodeEntry(desc);
    };


    GridWidget.prototype.updateNodeEntry = function(desc) {
        var self = this;
        var projectHtml,
            gmeId,
            panelId,
            title,
            image,
            authors,
            brief,
            description,
            svg,
            htmlId,
            html;
        
        title = desc.name;
        gmeId = desc.id;
        panelId = gmeId.replace(/\//g,'-');
        image = desc.image || DefaultIcon;
        authors = desc.authors;
        brief = desc.brief;
        description = desc.description;
        projectHtml = ejs.render(TEMPLATES['Project.html.ejs'], {
            id: panelId,
            title: title,
            image: image,
            authors: authors,
            brief: brief,
            description: description
        });

        self.$table.find('#'+panelId+'-node-panel').first().remove();
        self.$table.append(projectHtml);
        self.$table.find('#learn-'+panelId).click(function () {
            WebGMEGlobal.State.registerActiveObject(gmeId); 
            WebGMEGlobal.State.registerActiveVisualizer(VISUALIZER_INFO); 
        });

        // sort alphabetically
        var items = $(self.$table).children('div');
        items.detach().sort(function(a, b) {
            var contentA =$(a).data('sort');
            var contentB =$(b).data('sort');
            return (contentA < contentB) ? -1 : (contentA > contentB) ? 1 : 0;      
        });
        self.$table.append(items);

        function dialogPopup(gmeId, attrName) {
            var node = self._client.getNode(gmeId);
            var attr = node.getAttribute(attrName);
            var nodeName = node.getAttribute('name');
            var editorDialog = new DocumentEditorDialog("Edit " + attrName + " for " + nodeName);

            editorDialog.initialize(attr, function (text) {
                try {
                    self._client.setAttribute(gmeId, attrName, text, 'updated '+attrName+' for ' + gmeId);
                } catch (e) {
                    console.error('Could not save '+attrName+': ');
                    console.error(e);
                }
            });

            editorDialog.show();
        }

        if (!self._client.isProjectReadOnly()) {
            // editable authors area
            self.$el.find('#'+panelId+'-authors').on('click', _.bind(dialogPopup, self, gmeId, 'Authors'));
            // editable brief area
            self.$el.find('#'+panelId+'-brief').on('click', _.bind(dialogPopup, self, gmeId, 'Brief Description'));
            // editable detailed area
            self.$el.find('#'+panelId+'-detailed').on('click', _.bind(dialogPopup, self, gmeId, 'Detailed Description'));
        }

        htmlId = panelId + '-node-panel';
        html = self.$el.find('#' + htmlId);

        svg = html.find('svg');
        svg.css('height', '120px');
        svg.css('width', 'auto');

        html.addClass('panel-info');
        html.on('mouseenter', (event) => {
            html.addClass('panel-primary');
            html.removeClass('panel-info');
        });
        html.on('mouseleave', (event) => {
            html.addClass('panel-info');
            html.removeClass('panel-primary');
        });
        html.on('dblclick', (event) => {
            WebGMEGlobal.State.registerActiveSelection([desc.id]);
            self.onNodeClick(desc.id);
            event.stopPropagation();
            event.preventDefault();
        });
        var cm;
        // context menu:
        var onProjectItems = [
            {
                name: 'Open ' + desc.name,
                icon: '',
                doNotHide: false,
                callback: self.onNodeClick.bind(self)
            },
            {
                name: 'Copy ' + desc.name,
                icon: '',
                doNotHide: false,
                callback: self.copyProject.bind(self)
            },
            {
                name: 'Delete ' + desc.name,
                icon: '',
                doNotHide: false,
                callback: self.deleteProject.bind(self)
            }
        ];
        
        html.on('contextmenu', (event) => {
            // handle right click here
            // make menu with copy option
            // make menu with delete option
            var posX = event.clientX;
            var posY = event.clientY;

            cm = new ContextMenu({
                items: onProjectItems,
                callback: function(key) {
                    onProjectItems[key].callback(desc.id);
                    cm.destroy();
                }
            });

            cm.show({x: posX, y: posY});

            self.onNodeSelect(desc.id);
            event.stopPropagation();
            event.preventDefault();
        });

        self.nodes[desc.id] = desc;
    };

    // CONTEXT MENU FUNCTIONS

    GridWidget.prototype.deleteProject = function( gmeId ) {
        var self = this;
        self.setupTable();
        if (gmeId)
            self._client.deleteNode( gmeId, 'Deleting project: ' + gmeId);
        self._initialize();
    };

    GridWidget.prototype.copyProject = function( gmeId ) {
        var self = this;
        if (gmeId)
            self.copyChild( gmeId );
    };

