    // Adding/Removing/Updating items
    GridWidget.prototype.addNode = function (desc) {
        var self = this;
        let nodeObj = self._client.getNode(desc.id);
        if (desc && nodeObj) {
            var isValid = desc.meta !== 'Note' && desc.id !==  WebGMEGlobal.State.getActiveObject() && !nodeObj.isMetaNode() && !nodeObj.isLibraryRoot();

            if (isValid) {
                self.nodes[desc.id] = desc;
                self._tableSetup = true;
                self.createNodeEntry(desc);
            }
        }
    };

    GridWidget.prototype.removeNode = function (gmeId) {
        var self = this;
        if (self.nodes[gmeId]) {
            delete self.nodes[gmeId];
            self.setupTable();
            for (var id in self.nodes) {
                self.addNode(self.nodes[id]);
            }
        }
    };

    GridWidget.prototype.updateNode = function (desc) {
        var self = this;
        let nodeObj = self._client.getNode(desc.id);
        if (desc) {
            var isValid = desc.meta !== 'Note' && desc.id !==  WebGMEGlobal.State.getActiveObject() && !nodeObj.isMetaNode();
            if (isValid) {
                //self._nodes.push(desc);
                self.updateNodeEntry(desc);
            }
        }
    };

    GridWidget.prototype._isValidDrop = function (dragInfo) {
        var self = this;
        if (!dragInfo)
            return false;
        var self = this;
        var result = false,
            draggedNodePath,
            nodeObj,
            nodeName,
            metaObj,
            metaName;

        if (dragInfo[DROP_CONSTANTS.DRAG_ITEMS].length === 1) {
            draggedNodePath = dragInfo[DROP_CONSTANTS.DRAG_ITEMS][0];
            nodeObj = self._client.getNode(draggedNodePath);
            nodeName = nodeObj.getAttribute('name');
            metaObj = self._client.getNode(nodeObj.getMetaTypeId());
            if (metaObj) {
                metaName = metaObj.getAttribute('name');
            }
            result = metaName && metaName != 'Note';
        }

        return result;
    };
    GridWidget.prototype.createNode = function(nodePath, metaNodeId) {
        var self = this;
        this.createControl = true;
        var client = self._client;
        var parentId = WebGMEGlobal.State.getActiveObject(), // for our seeds, /v is always 'Projects'
            node = client.getNode(nodePath),
            baseId = metaNodeId ? metaNodeId : node.getBaseId(),
            baseNode = client.getNode(baseId),
            baseName = baseNode.getAttribute('name');

            var childCreationParams = {
                parentId: parentId,  // Should be Projects (/v)
                baseId: baseId,    // should be META:Project
            };
            client.createChild(childCreationParams, 'Creating new '+baseName);

    };
    GridWidget.prototype.copyChild = function(nodePath) {
        var self = this;
        var client = self._client;
        var parentId = WebGMEGlobal.State.getActiveObject(), // for our seeds, /v is always 'Projects'
            node = client.getNode(nodePath),
            nodeId = node.getId();

            var params = {parentId: parentId};
            params[nodeId] = {
                'attributes': {
                    'name': node.getAttribute('name') + ' Copy'
                }
            };
            self._client.startTransaction();
            self._client.copyMoreNodes(params);
            self._client.completeTransaction();

    };

